<?php

namespace App\Http\Controllers\Api;

use App\Http\Controllers\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;

class CourseController extends Controller
{
    public function catalog() { return response()->json(['categories' => $this->catalogData(true)]); }
    public function adminIndex() { return response()->json(['categories' => $this->catalogData(false)]); }

    public function detail(string $category, string $specialty, string $course)
    {
        $row = DB::table('courses as c')->join('course_specialties as s', 's.id', '=', 'c.specialty_id')->join('course_categories as cat', 'cat.id', '=', 's.category_id')->where(['cat.slug' => $category, 's.slug' => $specialty, 'c.slug' => $course, 'cat.published' => true, 's.published' => true, 'c.published' => true])->select('c.*', 's.title as specialty_title', 's.slug as specialty_slug', 'cat.title as category_title', 'cat.slug as category_slug')->first();
        abort_unless($row, 404);
        return response()->json($this->course($row));
    }

    public function createCategory(Request $request) { $data = $request->validate(['title' => ['required','string','max:255'], 'slug' => ['nullable','alpha_dash','max:100'], 'description' => ['nullable','string'], 'image' => ['nullable','string'], 'published' => ['boolean']]); $id = DB::table('course_categories')->insertGetId(['title' => $data['title'], 'slug' => $data['slug'] ?? Str::slug($data['title']), 'description' => $data['description'] ?? '', 'image' => $data['image'] ?? null, 'position' => (int) DB::table('course_categories')->max('position') + 1, 'published' => $data['published'] ?? true, 'created_at' => now(), 'updated_at' => now()]); return response()->json(DB::table('course_categories')->find($id), 201); }
    public function updateCategory(Request $request, int $id) { $data = $request->validate(['title' => ['required','string','max:255'], 'slug' => ['required','alpha_dash','max:100'], 'description' => ['nullable','string'], 'image' => ['nullable','string'], 'published' => ['required','boolean'], 'position' => ['required','integer','min:0']]); DB::table('course_categories')->where('id', $id)->update($data + ['updated_at' => now()]); return response()->json(DB::table('course_categories')->find($id)); }
    public function createSpecialty(Request $request) { $data = $request->validate(['categoryId' => ['required','integer','exists:course_categories,id'], 'title' => ['required','string','max:255'], 'slug' => ['nullable','alpha_dash','max:100'], 'description' => ['nullable','string'], 'heroTitle' => ['nullable','string'], 'heroSubtitle' => ['nullable','string'], 'image' => ['nullable','string'], 'published' => ['boolean']]); $id = DB::table('course_specialties')->insertGetId(['category_id' => $data['categoryId'], 'title' => $data['title'], 'slug' => $data['slug'] ?? Str::slug($data['title']), 'description' => $data['description'] ?? '', 'hero_title' => $data['heroTitle'] ?? '', 'hero_subtitle' => $data['heroSubtitle'] ?? '', 'image' => $data['image'] ?? null, 'position' => (int) DB::table('course_specialties')->where('category_id', $data['categoryId'])->max('position') + 1, 'published' => $data['published'] ?? true, 'created_at' => now(), 'updated_at' => now()]); return response()->json(DB::table('course_specialties')->find($id), 201); }
    public function updateSpecialty(Request $request, int $id) { $data = $request->validate(['title' => ['required','string','max:255'], 'slug' => ['required','alpha_dash','max:100'], 'description' => ['nullable','string'], 'heroTitle' => ['nullable','string'], 'heroSubtitle' => ['nullable','string'], 'image' => ['nullable','string'], 'published' => ['required','boolean'], 'position' => ['required','integer','min:0']]); DB::table('course_specialties')->where('id', $id)->update(['title'=>$data['title'],'slug'=>$data['slug'],'description'=>$data['description']??'','hero_title'=>$data['heroTitle']??'','hero_subtitle'=>$data['heroSubtitle']??'','image'=>$data['image']??null,'published'=>$data['published'],'position'=>$data['position'],'updated_at'=>now()]); return response()->json(DB::table('course_specialties')->find($id)); }
    public function createCourse(Request $request) { $data = $this->validateCourse($request, true); $id = DB::table('courses')->insertGetId(['specialty_id'=>$data['specialtyId'],'slug'=>$data['slug']??Str::slug($data['title']),'title'=>$data['title'],'summary'=>$data['summary']??'','trainer'=>$data['trainer']??'','duration'=>$data['duration']??'','badge'=>$data['badge']??'','format'=>$data['format']??'','image'=>$data['image']??null,'position'=>(int) DB::table('courses')->where('specialty_id',$data['specialtyId'])->max('position')+1,'published'=>$data['published']??true,'created_at'=>now(),'updated_at'=>now()]); $this->replaceModules($id, $data['modules'] ?? []); return response()->json($this->course(DB::table('courses')->find($id)), 201); }
    public function updateCourse(Request $request, int $id) { $data = $this->validateCourse($request, false); DB::table('courses')->where('id',$id)->update(['slug'=>$data['slug'],'title'=>$data['title'],'summary'=>$data['summary']??'','trainer'=>$data['trainer']??'','duration'=>$data['duration']??'','badge'=>$data['badge']??'','format'=>$data['format']??'','image'=>$data['image']??null,'position'=>$data['position'],'published'=>$data['published'],'updated_at'=>now()]); $this->replaceModules($id, $data['modules'] ?? []); return response()->json($this->course(DB::table('courses')->find($id))); }

    private function validateCourse(Request $request, bool $create): array { return $request->validate(array_merge($create ? ['specialtyId'=>['required','integer','exists:course_specialties,id']] : [], ['title'=>['required','string','max:255'],'slug'=>[$create?'nullable':'required','alpha_dash','max:100'],'summary'=>['nullable','string'],'trainer'=>['nullable','string','max:255'],'duration'=>['nullable','string','max:255'],'badge'=>['nullable','string','max:255'],'format'=>['nullable','string','max:255'],'image'=>['nullable','string'],'published'=>[$create?'boolean':'required|boolean'],'position'=>[$create?'nullable':'required|integer|min:0'],'modules'=>['array'],'modules.*'=>['string','max:3000']])); }
    private function replaceModules(int $courseId, array $modules): void { DB::table('course_modules')->where('course_id',$courseId)->delete(); foreach ($modules as $position => $body) if (trim($body) !== '') DB::table('course_modules')->insert(['course_id'=>$courseId,'body'=>$body,'position'=>$position,'created_at'=>now(),'updated_at'=>now()]); }
    private function catalogData(bool $published): array { $categories = DB::table('course_categories')->when($published, fn($q)=>$q->where('published',true))->orderBy('position')->get(); return $categories->map(function($category) use($published) { $specialties=DB::table('course_specialties')->where('category_id',$category->id)->when($published,fn($q)=>$q->where('published',true))->orderBy('position')->get(); return ['id'=>$category->id,'slug'=>$category->slug,'title'=>$category->title,'description'=>$category->description,'image'=>$category->image,'position'=>$category->position,'published'=>(bool)$category->published,'specialties'=>$specialties->map(function($specialty)use($published){$courses=DB::table('courses')->where('specialty_id',$specialty->id)->when($published,fn($q)=>$q->where('published',true))->orderBy('position')->get();return ['id'=>$specialty->id,'slug'=>$specialty->slug,'title'=>$specialty->title,'description'=>$specialty->description,'heroTitle'=>$specialty->hero_title,'heroSubtitle'=>$specialty->hero_subtitle,'image'=>$specialty->image,'position'=>$specialty->position,'published'=>(bool)$specialty->published,'courses'=>$courses->map(fn($course)=>$this->course($course))->all()];})->all()]; })->all(); }
    private function course(object $course): array { return ['id'=>$course->id,'slug'=>$course->slug,'title'=>$course->title,'summary'=>$course->summary,'trainer'=>$course->trainer,'duration'=>$course->duration,'badge'=>$course->badge,'format'=>$course->format,'image'=>$course->image,'position'=>$course->position,'published'=>(bool)$course->published,'modules'=>DB::table('course_modules')->where('course_id',$course->id)->orderBy('position')->pluck('body')->all(), 'categorySlug'=>$course->category_slug ?? null,'categoryTitle'=>$course->category_title ?? null,'specialtySlug'=>$course->specialty_slug ?? null,'specialtyTitle'=>$course->specialty_title ?? null]; }
}
